  Lemma hz_LB2_split : forall N q5 A q1 v q2 q q3 stb q4 va p1 allocb p2 regb p3 cfgb p4 schedb LB,
    exists NEW, hz_LB2 N q5 A q1 v q2 q q3 stb q4 va p1 allocb p2 regb p3 cfgb p4 schedb LB = NEW ++ LB /\ In (q3, stb, SZ_SPCI_STATE) NEW.
  Proof.
    intros. unfold hz_LB2, st_LB, mi_LB, hz_LB1. destruct (N =? 0).
    - exists [(q4, va, 8); (q3, stb, SZ_SPCI_STATE); (q2, q, SZ_SPCI_IMPL); (q1, v, NEWSZ_SSVC);
              (p4, schedb, NEWSZ_SCH); (p3, cfgb, NEWSZ_CFG); (p2, regb, NEWSZ_REG); (p1, allocb, SZ_ALLOCIMPL)]. split; [reflexivity| right; left; reflexivity].
    - exists [(q5, A, N); (q4, va, 8); (q3, stb, SZ_SPCI_STATE); (q2, q, SZ_SPCI_IMPL); (q1, v, NEWSZ_SSVC);
              (p4, schedb, NEWSZ_SCH); (p3, cfgb, NEWSZ_CFG); (p2, regb, NEWSZ_REG); (p1, allocb, SZ_ALLOCIMPL)]. split; [reflexivity| do 2 right; left; reflexivity].
  Qed.
